import z3
solver = z3.Solver()
x = [z3.Int(f'x{i}') for i in range(25)]
for i in range(25):
    solver.add(x[i] >= 0, x[i] <= 4)
for k in range(5):
    solver.add(z3.Sum([z3.If(x[i] == k, i+1, 0) for i in range(25)]) == 65)
if solver.check() == z3.sat:
    m = solver.model()
    sol = [m.evaluate(x[i]).as_long() for i in range(25)]
    print(sol)
else:
    print("unsat")
